<script lang="ts">
 import {onMount} from 'svelte';import * as env from '$app/env/public';import {loadGoogleMaps} from './google-maps';
 let {record,date,layer,boundary}:{record:any,date:string,layer:string,boundary?:any}=$props();
 let element:HTMLDivElement,map:google.maps.Map|undefined,overlay:google.maps.GroundOverlay|undefined;
 let ready=$state(false),busy=$state(false),message=$state(''),opacity=$state(.75),mode=$state('satellite');
 let disposed=false,controller:AbortController|undefined;
 let outline:google.maps.Polygon|undefined;
 onMount(()=>{disposed=false;void loadGoogleMaps(env.PUBLIC_GOOGLE_MAPS_API_KEY||'').then(api=>{if(disposed)return;map=new api.Map(element,{center:{lat:-17.8,lng:31.05},zoom:12,mapTypeId:'satellite',mapTypeControl:false,streetViewControl:false});ready=true;}).catch(e=>{if(!disposed)message=e.message;});return()=>{disposed=true;controller?.abort();overlay?.setMap(null);outline?.setMap(null);};});
 $effect(()=>{if(!ready||!map||!boundary?.coordinates?.[0])return;const paths=boundary.coordinates[0].map((p:number[])=>({lat:p[1],lng:p[0]}));outline?.setMap(null);outline=new google.maps.Polygon({map,paths,strokeColor:'#ffffff',strokeWeight:2,fillOpacity:0,clickable:false});const bounds=new google.maps.LatLngBounds();for(const point of paths)bounds.extend(point);map.fitBounds(bounds);});
 $effect(()=>{const d=date,l=layer,id=record.id;void d;void l;void id;overlay?.setMap(null);message='Choose Load mapped imagery to request a georeferenced provider raster.';});
 $effect(()=>{overlay?.setOpacity(opacity);map?.setMapTypeId(mode);});
 async function load(){busy=true;message='Preparing georeferenced imagery…';const requested={monitoring:record.id,date,layer};
  try{controller=new AbortController();const response=await fetch('/api/satellite/overlay',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(requested),signal:controller.signal});const result=await response.json();if(disposed||requested.monitoring!==record.id||requested.date!==date||requested.layer!==layer)return;if(!response.ok||result.state!=='ready')throw Error(result.error||'Provider raster is processing. Retry shortly.');overlay?.setMap(null);overlay=new google.maps.GroundOverlay(result.value.url,result.value.bounds,{opacity,clickable:false});overlay.setMap(map!);map!.fitBounds(result.value.bounds);message='Farmonaut mapped imagery · '+date+' · '+layer.toUpperCase()+'. Transparent pixels are outside your saved field.';
  }catch(e){if(!disposed)message=e instanceof Error?e.message:'Mapped imagery unavailable.';}finally{if(!disposed)busy=false;}
 }
</script>
<section class="geo-map"><h3>View imagery on the map</h3><div class="tools"><button type="button" class="p-button" disabled={!ready||busy||!date} onclick={load}>{busy?'Loading mapped imagery…':'Load mapped imagery'}</button><label>Map style<select bind:value={mode}><option value="satellite">Satellite</option><option value="hybrid">Hybrid</option><option value="roadmap">Street</option><option value="terrain">Terrain</option></select></label><label>Imagery opacity<input type="range" min="0" max="1" step="0.05" bind:value={opacity}/></label></div><p role="status">{message}</p><div class="map" bind:this={element}></div><p class="caption">Georeferencing must come from the raster itself. Unsupported formats stay unavailable; field-wide predictions are not converted to pest or nutrient hotspots.</p></section>
<style>.geo-map{padding:22px;border:1px solid #dce2d4;border-radius:14px;background:#fffef8;margin-bottom:24px;color:#163f32}h3{font-size:22px}.tools{display:flex;gap:16px;flex-wrap:wrap;align-items:end}label{display:grid;gap:6px;font-size:12px}select{padding:10px;border:1px solid #becbab;border-radius:6px;background:#fffef8}.map{height:450px;border-radius:10px;background:#eaf0e2}p{font-size:12px;line-height:1.7}.caption{color:#61745e;font-size:11px}@media(max-width:600px){.map{height:340px}}</style>
